//! Font atlases generated by tools/mkfont.py (Roboto Regular/Medium, Apache License 2.0): one set per text size
//! (Display > Text size), each with the same seven faces.

pub struct Glyph {
    pub cp: u32,
    pub w: i32,
    pub h: i32,
    pub x0: i32,
    pub y0: i32,
    pub adv: i32,
    pub off: usize,
}

pub struct Font {
    pub size: i32,
    #[allow(dead_code)] // part of the atlas format, kept for line spacing
    pub ascent: i32,
    #[allow(dead_code)]
    pub descent: i32,
    pub glyphs: Vec<Glyph>,
    pub alpha: &'static [u8],
}

/// s/m/l/xl = Roboto Regular 12/14/20/26 px, sb/mb/lb = Roboto Medium 12/14/18 px at the normal text size; 2 px
/// bigger each at Large, 4 px at Larger.
pub struct Fonts {
    pub s: Font,
    pub sb: Font,
    pub m: Font,
    pub mb: Font,
    pub l: Font,
    pub lb: Font,
    #[allow(dead_code)] // reserved for large read-outs
    pub xl: Font,
}

/// The atlases by text size: normal, large, larger.
static BLOBS: [&[u8]; 3] = [include_bytes!("../assets/font.bin"), include_bytes!("../assets/font-large.bin"), include_bytes!("../assets/font-larger.bin")];

fn u16le(b: &[u8], o: usize) -> u16 {
    u16::from_le_bytes([b[o], b[o + 1]])
}
fn i16le(b: &[u8], o: usize) -> i16 {
    i16::from_le_bytes([b[o], b[o + 1]])
}
fn u32le(b: &[u8], o: usize) -> u32 {
    u32::from_le_bytes([b[o], b[o + 1], b[o + 2], b[o + 3]])
}

impl Font {
    pub fn glyph(&self, ch: char) -> &Glyph {
        let cp = ch as u32;
        if (32..127).contains(&cp) {
            return &self.glyphs[(cp - 32) as usize];
        }
        self.glyphs.iter().skip(95).find(|g| g.cp == cp).unwrap_or(&self.glyphs[('?' as usize) - 32])
    }
    pub fn width(&self, s: &str) -> i32 {
        s.chars().map(|c| self.glyph(c).adv).sum()
    }
}

impl Fonts {
    /// The set of text size `k` (0 normal, 1 large, 2 larger), loaded on first use.
    pub fn get(k: usize) -> &'static Fonts {
        static SETS: [std::sync::OnceLock<Fonts>; 3] = [std::sync::OnceLock::new(), std::sync::OnceLock::new(), std::sync::OnceLock::new()];
        let k = k.min(SETS.len() - 1);
        SETS[k].get_or_init(|| Fonts::load(BLOBS[k]))
    }

    fn load(b: &'static [u8]) -> Fonts {
        assert_eq!(&b[0..4], b"OOSF");
        let count = u16le(b, 4) as usize;
        assert_eq!(count, 7);
        let mut o = 6;
        let mut v = Vec::new();
        for _ in 0..count {
            let size = u16le(b, o) as i32;
            let ascent = u16le(b, o + 2) as i32;
            let descent = u16le(b, o + 4) as i32;
            let n = u16le(b, o + 6) as usize;
            let alen = u32le(b, o + 8) as usize;
            o += 12;
            let mut glyphs = Vec::with_capacity(n);
            for _ in 0..n {
                glyphs.push(Glyph {
                    cp: u32le(b, o),
                    w: i16le(b, o + 4) as i32,
                    h: i16le(b, o + 6) as i32,
                    x0: i16le(b, o + 8) as i32,
                    y0: i16le(b, o + 10) as i32,
                    adv: i16le(b, o + 12) as i32,
                    off: u32le(b, o + 16) as usize,
                });
                o += 20;
            }
            let alpha = &b[o..o + alen];
            o += alen;
            v.push(Font { size, ascent, descent, glyphs, alpha });
        }
        let mut it = v.into_iter();
        let mut next = || it.next().unwrap();
        Fonts { s: next(), sb: next(), m: next(), mb: next(), l: next(), lb: next(), xl: next() }
    }
}
